1406	/// `PUT /-/pnpm/v1/publish` — publish several packages with one
1407	/// request. The body is `{"packages": [<publish doc>, ...]}` where
1408	/// each entry is exactly the JSON body that `PUT /:pkg` takes
1409	/// (packument with `_attachments`). `pnpm publish --batch` sends
1410	/// this; the endpoint is not part of the standard npm registry API.
1411	///
1412	/// The batch is all-or-nothing up to the commit point: every
1413	/// document is validated (name, publish policy, attachment
1414	/// integrity) and every tarball of every package is fully written
1415	/// to a tmp slot before anything becomes visible to readers, so a
1416	/// batch that fails validation or staging leaves no new versions
1417	/// behind.
1418	async fn serve_batch_publish(
1419	    State(state): State<AppState>,
1420	    AuthedCaller(identity): AuthedCaller,
1421	    body: axum::body::Bytes,
1422	) -> Response {
1423	    let incoming: Value = match serde_json::from_slice(&body) {
1424	        Ok(v) => v,
1425	        Err(err) => return error_response(&RegistryError::Json(err)),
1426	    };
1427	    let Value::Object(mut incoming) = incoming else {
1428	        return error_response(&RegistryError::BadRequest {
1429	            reason: "body must be a JSON object".to_string(),
1430	        });
1431	    };
1432	    let Some(Value::Array(docs)) = incoming.remove("packages") else {
1433	        return error_response(&RegistryError::BadRequest {
1434	            reason: "body must have a `packages` array".to_string(),
1435	        });
1436	    };
1437	    if docs.is_empty() {
1438	        return error_response(&RegistryError::BadRequest {
1439	            reason: "`packages` must not be empty".to_string(),
1440	        });
1441	    }
1442	
1443	    let mut validated = Vec::with_capacity(docs.len());
1444	    let mut seen_names = std::collections::BTreeSet::new();
1445	    for doc in docs {
1446	        let Some(doc_name) = doc.get("name").and_then(Value::as_str) else {
1447	            return error_response(&RegistryError::BadRequest {
1448	                reason: "every entry in `packages` must have a string `name`".to_string(),
1449	            });
1450	        };
