                "version": "1.0.0",
                "dependencies": { "left-pad": "^1.0.0" },
                "deprecated": "old warning",
                "dist": { "integrity": "sha512-HOSTED", "tarball": "http://x/foo-1.0.0.tgz" }
            }
        }
    });

    // Case A: metadata-only republish changing deps + deprecated. Hosted wins
    // except deprecated is replaced.
    let incoming_a = json!({
        "name": "foo",
        "versions": {
            "1.0.0": {
                "version": "1.0.0",
                "dependencies": { "left-pad": "^9.9.9", "evil": "1.0.0" },
                "deprecated": "new warning",
                "dist": { "integrity": "sha512-EVIL", "tarball": "http://x/foo-1.0.0.tgz" }
            }
        }
    });
    let a = merge_manifest(Some(&hosted), &incoming_a, Some(&hosted), now);
    let v = &a["versions"]["1.0.0"];
    assert_eq!(v["dist"]["integrity"], "sha512-HOSTED", "integrity must be preserved");
    assert_eq!(v["dependencies"]["left-pad"], "^1.0.0", "deps must be preserved");
    assert!(v["dependencies"].get("evil").is_none(), "smuggled dep must not appear");
    assert_eq!(v["deprecated"], "new warning", "deprecated replaced");

    // Case B: incoming omits deprecated -> key removed.
    let incoming_b = json!({
        "versions": { "1.0.0": { "version": "1.0.0", "dist": { "integrity": "sha512-EVIL" } } }
    });
    let b = merge_manifest(Some(&hosted), &incoming_b, Some(&hosted), now);
    let v = &b["versions"]["1.0.0"];
    assert_eq!(v["dist"]["integrity"], "sha512-HOSTED");
    assert!(v.get("deprecated").is_none(), "deprecated must be removed when omitted");

    // Case C: incoming entry is null -> ignored, hosted preserved unchanged
    // (including its original deprecated).
    let incoming_c = json!({ "versions": { "1.0.0": null } });
    let c = merge_manifest(Some(&hosted), &incoming_c, Some(&hosted), now);
    let v = &c["versions"]["1.0.0"];
    assert_eq!(v["dist"]["integrity"], "sha512-HOSTED");
    assert_eq!(v["deprecated"], "old warning", "null entry must leave hosted untouched");

    // Case D: hosted None -> incoming wins for all versions.
    let existing = json!({ "versions": { "1.0.0": { "version": "1.0.0", "dist": { "integrity": "sha512-UP" } } } });
    let incoming_d = json!({ "versions": { "1.0.0": { "version": "1.0.0", "dist": { "integrity": "sha512-NEW" } } } });
    let d = merge_manifest(Some(&existing), &incoming_d, None, now);
    assert_eq!(d["versions"]["1.0.0"]["dist"]["integrity"], "sha512-NEW", "hosted None -> incoming wins");

    println!("all scratch assertions passed");
}
